import pytest

class MockController:
    def __init__(self, tube_connected=True):
        self.tube_connected = tube_connected

    def is_proximal_tube_connected(self):
        return self.tube_connected

class MockGUI:
    def __init__(self):
        self.alarm_active = {}
        self.alarm_priority = {}
        self.vti = 0.0

    def set_vti(self, vti):
        self.vti = vti

    def get_alarm_status(self, alarm_name):
        return self.alarm_active.get(alarm_name, False)

    def get_alarm_priority(self, alarm_name):
        return self.alarm_priority.get(alarm_name, None)

    def compute_obstruction_alarm(self):
        if self.vti < 100:
            self.alarm_active['obstruction'] = True
            self.alarm_priority['obstruction'] = 'high'
        else:
            self.alarm_active['obstruction'] = False

    def set_proximal_tube_disconnected(self, disconnected):
        if disconnected:
            self.alarm_active['proximal_tube_disconnect'] = True
            self.alarm_priority['proximal_tube_disconnect'] = 'medium'
        else:
            self.alarm_active['proximal_tube_disconnect'] = False

    def compute_leakage(self, sensor_readings):
        flow = sensor_readings.get('flow', 0)
        return flow / 1000.0

def test_rw_sw_103_connected():
    controller = MockController(tube_connected=True)
    assert controller.is_proximal_tube_connected() is True

def test_rw_sw_104_105():
    gui = MockGUI()
    gui.set_proximal_tube_disconnected(True)
    assert gui.get_alarm_status('proximal_tube_disconnect') is True
    assert gui.get_alarm_priority('proximal_tube_disconnect') == 'medium'

def test_rw_sw_106_107_109():
    gui = MockGUI()
    gui.set_vti(99.9)
    gui.compute_obstruction_alarm()
    assert gui.get_alarm_status('obstruction') is True
    assert gui.get_alarm_priority('obstruction') == 'high'

def test_rw_sw_108():
    gui = MockGUI()
    gui.set_vti(100.0)
    gui.compute_obstruction_alarm()
    assert gui.get_alarm_status('obstruction') is False

def test_rw_sw_110():
    gui = MockGUI()
    sensor_readings = {'flow': 100}
    leakage = gui.compute_leakage(sensor_readings)
    assert isinstance(leakage, (int, float))
    assert leakage >= 0

